import fs2 from "fs/promises";
import path2 from "path";
import https2 from "https";
import http2 from "http";

var ParameterService = class {
    constructor(icedqClient, authService) {
        this.client = icedqClient;
        this.auth = authService;
    }

    async createParameter(workspaceId, folderId, parameterName, parameterKey, parameterValue, description = null) {
        log("info", "Creating parameter", {
            workspaceId,
            folderId,
            parameterName,
            parameterKey,
            parameterValue,
            description
        });
        const requestBody = {
            name: parameterName,
            type: "default",
            info: {
                ...description ? {description} : {},
                parameters: [
                    {
                        key: parameterKey,
                        value: parameterValue,
                        type: "system"
                    }
                ]
            }
        };
        log("info", "Parameter payload built", {
            parameterName,
            parameterKey,
            hasDescription: !!description
        });
        await this.auth.ensureAuthenticated();
        const response = await this.client.icedqRequest("/parameters", {
            method: "POST",
            headers: {
                "workspace-id": workspaceId,
                "folder-id": folderId
            },
            body: requestBody
        }, this.auth.getToken());
        log("info", "Parameter created successfully", {
            parameterId: response.id,
            parameterName: response.name,
            type: response.type
        });
        return {
            success: true,
            workspaceId,
            folderId,
            parameterId: response.id,
            parameterName: response.name,
            parameterType: response.type,
            description: response.info?.description,
            parameters: response.info?.parameters || [],
            createdBy: response.createdBy,
            createdAt: response.createdTimestamp,
            message: `Parameter '${response.name}' created successfully`
        };
    }

    async updateParameter(workspaceId, parameterId, parameterName, parameterType = "default", description = null, parameters) {
        log("info", "Updating parameter", {
            workspaceId,
            parameterId,
            parameterName,
            parameterType,
            description,
            parametersCount: parameters ? parameters.length : 0
        });
        const normalizedParams = (parameters || []).map((p) => ({
            key: p.key,
            value: p.value,
            type: "system"
        }));
        const info = {
            parameters: normalizedParams
        };
        if (description !== null && description !== void 0) {
            info.description = description;
        }
        const requestBody = {
            id: parameterId,
            name: parameterName,
            type: "default",
            info
        };
        log("info", "Parameter update payload built", {
            parameterId,
            parameterName,
            type: parameterType,
            hasDescription: !!description,
            parametersCount: requestBody.info.parameters ? requestBody.info.parameters.length : 0
        });
        await this.auth.ensureAuthenticated();
        const response = await this.client.icedqRequest(`/parameters/${parameterId}`, {
            method: "PUT",
            headers: {
                "workspace-id": workspaceId
            },
            body: requestBody
        }, this.auth.getToken());
        log("info", "Parameter updated successfully", {
            parameterId: response.id,
            parameterName: response.name,
            type: response.type
        });
        return {
            success: true,
            workspaceId,
            parameterId: response.id,
            parameterName: response.name,
            parameterType: response.type,
            description: response.info?.description,
            parameters: response.info?.parameters || [],
            updatedBy: response.updatedBy,
            updatedAt: response.updatedTimestamp,
            message: `Parameter '${response.name}' updated successfully`
        };
    }

    async parseCsvAndCreateParameter(workspaceId, folderId, csvFilePath, parameterName, parameterType = "default", description = null) {
        log("info", "Parsing CSV and creating parameter", {
            workspaceId,
            folderId,
            csvFilePath,
            parameterName,
            parameterType,
            description
        });
        try {
            await fs2.access(csvFilePath);
        } catch {
            throw new McpError(
                ErrorCode.InvalidParams,
                `CSV file not found: ${csvFilePath}`
            );
        }
        const fileStats = await fs2.stat(csvFilePath);
        const fileName = path2.basename(csvFilePath);
        const MAX_CSV_SIZE = 50 * 1024 * 1024;
        if (fileStats.size === 0) {
            throw new McpError(
                ErrorCode.InvalidParams,
                "CSV file is empty"
            );
        }
        if (fileStats.size > MAX_CSV_SIZE) {
            throw new McpError(
                ErrorCode.InvalidParams,
                `CSV file is too large (${(fileStats.size / 1024 / 1024).toFixed(1)} MB). Maximum allowed size is 50 MB.`
            );
        }
        try {
            log("info", "Step 1: Parsing CSV file", {fileName, fileSize: fileStats.size});
            const fileContent = await fs2.readFile(csvFilePath);
            const boundary = "----WebKitFormBoundary" + Math.random().toString(36).substring(2, 15);
            const formData = Buffer.concat([
                Buffer.from(`--${boundary}\r
`),
                Buffer.from(`Content-Disposition: form-data; name="file"; filename="${fileName}"\r
`),
                Buffer.from(`Content-Type: text/csv\r
\r
`),
                fileContent,
                Buffer.from(`\r
--${boundary}--\r
`)
            ]);
            await this.auth.ensureAuthenticated();
            const accessToken = this.auth.getToken();
            const baseUrl = this.client.config.baseUrl;
            const parseUrl = `${baseUrl}/api/v1/parameters:parse`;
            const parseHeaders = {
                "Authorization": `Bearer ${accessToken}`,
                "Accept": "application/json, text/plain, */*",
                "Content-Type": `multipart/form-data; boundary=${boundary}`,
                "Content-Length": formData.length,
                "workspace-id": workspaceId
            };
            if (this.client.config.orgId) {
                parseHeaders["Org-Id"] = this.client.config.orgId;
            }
            log("debug", "Parsing CSV with multipart request", {
                url: parseUrl,
                fileName,
                fileSize: fileStats.size
            });
            const parseResponse = await this._makeMultipartRequest(parseUrl, {
                method: "POST",
                headers: parseHeaders,
                body: formData
            });
            log("info", "CSV parsed successfully", {
                responseType: typeof parseResponse,
                hasData: !!parseResponse
            });
            let parameters = [];
            if (Array.isArray(parseResponse)) {
                parameters = parseResponse.map((item) => ({
                    key: item.parameter_key || item.key || `param_${Date.now()}`,
                    value: item.parameter_value || item.value || "",
                    type: "system"
                }));
            } else if (parseResponse && typeof parseResponse === "object") {
                if (parseResponse.parameters && Array.isArray(parseResponse.parameters)) {
                    parameters = parseResponse.parameters.map((p) => ({
                        key: p.key,
                        value: p.value,
                        type: "system"
                    }));
                } else {
                    parameters = Object.entries(parseResponse).map(([key, value]) => ({
                        key,
                        value: String(value),
                        type: "system"
                    }));
                }
            } else {
                throw new McpError(
                    ErrorCode.InternalError,
                    "Unable to parse CSV response into parameters"
                );
            }
            if (parameters.length === 0) {
                throw new McpError(
                    ErrorCode.InternalError,
                    "No parameters found in CSV file"
                );
            }
            log("info", "Parameters extracted from CSV", {
                parameterCount: parameters.length
            });
            log("info", "Step 2: Creating parameter with parsed data");
            const requestBody = {
                name: parameterName,
                type: "default",
                info: {
                    ...description ? {description} : {},
                    parameters
                }
            };
            const createResponse = await this.client.icedqRequest("/parameters", {
                method: "POST",
                headers: {
                    "workspace-id": workspaceId,
                    "folder-id": folderId
                },
                body: requestBody
            }, this.auth.getToken());
            log("info", "Parameter created successfully from CSV", {
                parameterId: createResponse.id,
                parameterName: createResponse.name,
                parameterCount: parameters.length
            });
            return {
                success: true,
                workspaceId,
                folderId,
                csvFile: {
                    path: csvFilePath,
                    name: fileName,
                    size: fileStats.size
                },
                parseResponse,
                parameter: {
                    id: createResponse.id,
                    name: createResponse.name,
                    type: createResponse.type,
                    description: createResponse.info?.description,
                    parameters,
                    createdBy: createResponse.createdBy,
                    createdAt: createResponse.createdTimestamp
                },
                message: `Successfully parsed CSV file '${fileName}' and created parameter '${createResponse.name}' with ${parameters.length} parameter(s)`
            };
        } catch (error2) {
            if (error2 instanceof McpError) throw error2;
            log("error", "Failed to parse CSV and create parameter", {
                error: error2.message,
                csvFilePath,
                parameterName
            });
            throw new McpError(
                ErrorCode.InternalError,
                `Failed to parse CSV and create parameter: ${error2.message}`
            );
        }
    }

    _makeMultipartRequest(url2, options = {}) {
        return new Promise((resolve, reject) => {
            const urlObj = new URL(url2);
            const isHttps = urlObj.protocol === "https:";
            const httpModule = isHttps ? https2 : http2;
            const reqOptions = {
                method: options.method || "POST",
                headers: options.headers || {},
                timeout: this.client.config.requestTimeout
            };
            if (isHttps && !this.client.config.verifySsl) {
                reqOptions.rejectUnauthorized = false;
            }
            const req = httpModule.request(url2, reqOptions, (res) => {
                let data = "";
                res.on("data", (chunk) => {
                    data += chunk;
                });
                res.on("end", () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        try {
                            resolve(data ? JSON.parse(data) : {});
                        } catch (e) {
                            resolve(data);
                        }
                    } else {
                        reject(new Error(`HTTP ${res.statusCode}: ${data}`));
                    }
                });
            });
            req.on("error", reject);
            req.on("timeout", () => {
                req.destroy();
                reject(new Error("Multipart request timeout"));
            });
            if (options.body) {
                req.write(options.body);
            }
            req.end();
        });
    }
};

